  function slug(text) {
    return String(text).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  function setQuestion(questionId, selections) {
    const ids = selections.map(([term, fallback, usage], index) => {
      const key = String(term).toLowerCase();
      const source = sourceByQuestionAndTerm[questionId][key] || authored[`${questionId}::${key}`];
      if (!source) {
        issues.push(`${questionId}: missing source for ${term}`);
        return "";
      }
      const examples = Array.isArray(source.examples) && source.examples.length
        && Array.isArray(source.examples[0])
        ? source.examples
        : (source.examples || []).map((item, i) => [item, (source.examplesZh || [])[i]]);
      const id = `v31-${questionId.toLowerCase()}-${slug(term) || `card-${index + 1}`}`;
      if (!fallback) issues.push(`${questionId}: ${term} has no Band 6 fallback target`);
      if (!usage) issues.push(`${questionId}: ${term} has no exact-essay function`);
      if (/[.!?]$/.test(term)) issues.push(`${questionId}: sentence-like card front ${term}`);
      if (!Array.isArray(examples) || examples.length !== 3
        || examples.some((item) => !Array.isArray(item) || item.length !== 2 || !item[0] || !item[1])) {
        issues.push(`${questionId}: ${term} needs three bilingual examples`);
      }
      glossary[id] = {
        id,
        term: source.term,
        ipa: String(source.ipa || ""),
        pos: source.pos,
        meaning: source.meaning,
        zh: source.zh,
        zh_def: source.zh_def,
        note: `本題升級：用「${term}」取代較弱表達「${fallback}」。${usage}`,
        examples: examples.map((item) => String(item[0])),
        examplesZh: examples.map((item) => String(item[1])),
        scopeQuestionId: questionId,
        replacesBasic: fallback,
        essayFunction: usage,
        learningTier: "exact-essay-upgrade",
      };
      return id;
    }).filter(Boolean);
    if (!ids.length) issues.push(`${questionId}: no V31 cards`);
    if (new Set(ids).size !== ids.length) issues.push(`${questionId}: duplicate V31 ids`);
    questionKeywords[questionId] = ids;
  }

