(function () {
  "use strict";

  // V36 records the 25 sets approved after the V35 calibration. Selection is
  // editorial, not numerical: every card must replace weaker wording and do a
  // distinct job in the exact report or essay. Card counts therefore vary by
  // question. Core words stay on the front; useful collocations stay in the
  // examples and explanation on the back.
  const glossary = window.WRITING_EXACT_KEYWORD_GLOSSARY = window.WRITING_EXACT_KEYWORD_GLOSSARY || {};
  const questionKeywords = window.WRITING_EXACT_QUESTION_KEYWORDS = window.WRITING_EXACT_QUESTION_KEYWORDS || {};
  const state = window.WRITING_TWENTY_FIVE_QUESTION_UPDATE_V36_STATE = {
    reviewedQuestions: [],
    questionCardCounts: {},
    expectedTerms: {},
    cards: [],
    issues: [],
  };

  function slug(text) {
    return String(text).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  function addPack(questionId, cards) {
    if (state.reviewedQuestions.includes(questionId)) {
      state.issues.push(`${questionId}: duplicate V36 question pack`);
      return;
    }
    if (!Array.isArray(cards) || !cards.length) {
      state.issues.push(`${questionId}: every question must have useful cards`);
      return;
    }

    const ids = cards.map((card, index) => {
      const id = `v36-${questionId.toLowerCase()}-${slug(card.term) || `card-${index + 1}`}`;
      if (!card.term || !card.pos || !card.meaning || !card.zh) {
        state.issues.push(`${questionId}: card ${index + 1} is missing its learner-facing definition`);
      }
      if (!card.fallback) state.issues.push(`${questionId}: ${card.term} has no weaker-expression target`);
      if (!card.essayFunction) state.issues.push(`${questionId}: ${card.term} has no exact-answer function`);
      if (!Array.isArray(card.examples) || card.examples.length !== 3
        || card.examples.some((item) => !Array.isArray(item) || item.length !== 2 || !item[0] || !item[1])) {
        state.issues.push(`${questionId}: ${card.term} needs three bilingual examples`);
      }

      glossary[id] = {
        id,
        term: card.term,
        ipa: "",
        pos: card.pos,
        meaning: card.meaning,
        zh: card.zh,
        zh_def: card.zhDef || `在本題中用來表達「${card.zh}」。`,
        note: `本題升級：用「${card.term}」取代較弱表達「${card.fallback}」。${card.essayFunction}`,
        examples: (card.examples || []).map((item) => item[0]),
        examplesZh: (card.examples || []).map((item) => item[1]),
        scopeQuestionId: questionId,
        replacesBasic: card.fallback,
        essayFunction: card.essayFunction,
        learningTier: "approved-exact-answer-upgrade-v36",
      };
      state.cards.push(glossary[id]);
      return id;
    });

    if (new Set(ids).size !== ids.length) state.issues.push(`${questionId}: duplicate V36 card ids`);
    questionKeywords[questionId] = ids;
    state.reviewedQuestions.push(questionId);
    state.questionCardCounts[questionId] = ids.length;
    state.expectedTerms[questionId] = cards.map((card) => card.term);
  }

  window.WRITING_V36_ADD_PACK = addPack;
})();

/* END data/writing_keyword_update_v36_core.js */

;

