/* BEGIN data/writing_keyword_update_v37_core.js */
(function () {
  "use strict";

  // V37 contains the three five-question batches approved after V36. The
  // selection is editorial, not numerical: a card survives only when it helps
  // answer that exact Cambridge prompt and is worth learning for Band 7–8.
  const glossary = window.WRITING_EXACT_KEYWORD_GLOSSARY = window.WRITING_EXACT_KEYWORD_GLOSSARY || {};
  const questionKeywords = window.WRITING_EXACT_QUESTION_KEYWORDS = window.WRITING_EXACT_QUESTION_KEYWORDS || {};
  const state = window.WRITING_FIFTEEN_QUESTION_UPDATE_V37_STATE = {
    reviewedQuestions: [],
    questionCardCounts: {},
    expectedTerms: {},
    cards: [],
    issues: [],
  };

  function slug(text) {
    return String(text).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  function sourceCard(questionId, term) {
    const candidates = Object.values(glossary).filter((card) => (
      card && card.scopeQuestionId === questionId && card.term === term
    ));
    return candidates.length ? candidates[candidates.length - 1] : null;
  }

  function resolveCard(questionId, spec, index) {
    const source = spec.sourceTerm ? sourceCard(questionId, spec.sourceTerm) : null;
    if (spec.sourceTerm && !source) {
      state.issues.push(`${questionId}: source card not found for ${spec.term} (${spec.sourceTerm})`);
    }
    const card = Object.assign({}, source || {}, spec);
    delete card.id;
    delete card.sourceTerm;

    if (Array.isArray(card.examplePairs)) {
      card.examples = card.examplePairs.map((pair) => pair[0]);
      card.examplesZh = card.examplePairs.map((pair) => pair[1]);
      delete card.examplePairs;
    }

    if (!card.term || !card.pos || !card.meaning || !card.zh) {
      state.issues.push(`${questionId}: card ${index + 1} is missing its learner-facing definition`);
    }
    if (!card.fallback && !card.replacesBasic) {
      state.issues.push(`${questionId}: ${card.term || `card ${index + 1}`} has no weaker-expression target`);
    }
    if (!card.essayFunction) {
      state.issues.push(`${questionId}: ${card.term || `card ${index + 1}`} has no exact-answer function`);
    }
    if (!Array.isArray(card.examples) || !Array.isArray(card.examplesZh)
      || card.examples.length !== 3 || card.examplesZh.length !== 3
      || card.examples.some((item) => !item) || card.examplesZh.some((item) => !item)) {
      state.issues.push(`${questionId}: ${card.term || `card ${index + 1}`} needs three bilingual examples`);
    }
    return card;
  }

  function addPack(questionId, specs) {
    if (state.reviewedQuestions.includes(questionId)) {
      state.issues.push(`${questionId}: duplicate V37 question pack`);
      return;
    }
    if (!Array.isArray(specs) || !specs.length) {
      state.issues.push(`${questionId}: every question must have useful cards`);
      return;
    }

    const cards = specs.map((spec, index) => resolveCard(questionId, spec, index));
    const ids = cards.map((card, index) => {
      const id = `v37-${questionId.toLowerCase()}-${slug(card.term) || `card-${index + 1}`}`;
      const replacesBasic = card.fallback || card.replacesBasic;
      glossary[id] = {
        id,
        term: card.term,
        ipa: "",
        pos: card.pos,
        meaning: card.meaning,
        zh: card.zh,
        zh_def: card.zhDef || `在本題中用來表達「${card.zh}」。`,
        note: `本題升級：用「${card.term}」取代較弱表達「${replacesBasic}」。${card.essayFunction}`,
        examples: card.examples.slice(),
        examplesZh: card.examplesZh.slice(),
        scopeQuestionId: questionId,
        replacesBasic,
        essayFunction: card.essayFunction,
        learningTier: "approved-exact-answer-upgrade-v37",
      };
      state.cards.push(glossary[id]);
      return id;
    });

    if (new Set(ids).size !== ids.length) state.issues.push(`${questionId}: duplicate V37 card ids`);
    questionKeywords[questionId] = ids;
    state.reviewedQuestions.push(questionId);
    state.questionCardCounts[questionId] = ids.length;
    state.expectedTerms[questionId] = cards.map((card) => card.term);
  }

  window.WRITING_V37_ADD_PACK = addPack;
})();

/* END data/writing_keyword_update_v37_core.js */

