/* BEGIN data/writing_keyword_update_v37_finalize.js */
(function () {
  "use strict";

  const state = window.WRITING_FIFTEEN_QUESTION_UPDATE_V37_STATE;
  const glossary = window.WRITING_EXACT_KEYWORD_GLOSSARY || {};
  const questionKeywords = window.WRITING_EXACT_QUESTION_KEYWORDS || {};
  const issues = state && Array.isArray(state.issues) ? state.issues : ["V37 state was not loaded."];

  const approvedTerms = {
    "C14-W1-T3": ["cyclical", "alternate", "harness", "reverse", "recirculate"],
    "C14-W1-T4": ["transform", "repurpose", "relocate", "retain"],
    "C14-W2-T1": ["pragmatic", "endure", "constraint", "viable", "strive", "incremental", "stagnate"],
    "C14-W2-T2": ["biodiversity", "interdependent", "disrupt", "irreversible", "underlie", "pressing"],
    "C14-W2-T3": ["bridge", "resonate", "evoke", "transmit", "diverge"],
    "C14-W2-T4": ["autonomy", "lucrative", "volatile", "forgo", "shoulder", "burden", "isolation"],
    "C15-W1-T1": ["predominate", "trail", "edge", "cluster", "parity"],
    "C15-W1-T2": ["triple", "plateau", "fluctuate", "rebound", "outpace", "overtake"],
    "C15-W1-T3": ["linear", "transform", "incorporate", "culminate"],
    "C15-W1-T4": ["predominate", "bracket", "align", "skew", "lag"],
    "C15-W2-T1": ["permanence", "prestige", "equity", "appreciate", "affordability", "overextend", "default"],
    "C15-W2-T2": ["obsolete", "displace", "circulation", "paywall", "tactile", "persist"],
    "C15-W2-T4": ["aspiration", "persevere", "resilience", "attainable", "conflate", "constraint", "self-blame", "burnout"],
    "C16-W1-T1": ["uptake", "inverse", "surge", "universal", "taper", "rebound", "halve"],
    "C16-W1-T2": ["cultivate", "mechanised", "extract", "purify", "concentrate", "yield"],
  };
  const approvedCounts = Object.fromEntries(Object.entries(approvedTerms).map(([id, terms]) => [id, terms.length]));
  const rejectedFronts = [
    "bus station", "staff car park", "shopping centre", "inject", "turbine", "generator",
    "be pumped to a depth of", "be channelled back to the surface", "set the turbine in motion",
    "drive a generator", "electricity distribution", "post-harvest losses", "food insecurity",
    "curriculum continuity", "transferable skills", "digital literacy", "instant gratification",
    "diminished attention span", "compulsive use", "sedentary behaviour", "cultural homogenization",
    "active ageing", "civil liberties", "income inequality", "monetise", "isolate",
    "consolidate", "pervasive", "bond", "portion",
  ];

  const reviewedQuestions = state ? state.reviewedQuestions.slice() : [];
  const cards = state ? state.cards.slice() : [];
  const questionCardCounts = state ? Object.assign({}, state.questionCardCounts) : {};

  if (JSON.stringify(reviewedQuestions) !== JSON.stringify(Object.keys(approvedTerms))) {
    issues.push("V37 reviewed-question order or scope drifted from the three approved batches");
  }
  Object.entries(approvedTerms).forEach(([questionId, terms]) => {
    if (questionCardCounts[questionId] !== terms.length) {
      issues.push(`${questionId}: expected ${terms.length} approved cards, found ${questionCardCounts[questionId] || 0}`);
    }
    const liveTerms = (questionKeywords[questionId] || []).map((id) => glossary[id] && glossary[id].term);
    if (JSON.stringify(liveTerms) !== JSON.stringify(terms)) {
      issues.push(`${questionId}: V37 selection drifted before finalisation`);
    }
  });

  const selectedTerms = new Set(cards.map((card) => String(card.term || "").toLowerCase()));
  rejectedFronts.forEach((term) => {
    if (selectedTerms.has(term)) issues.push(`Rejected V37 card front returned: ${term}`);
  });

  const normalise = (text) => String(text).toLowerCase().replace(/[^a-z0-9]+/g, "");
  cards.forEach((card) => {
    const normalisedTerm = normalise(card.term);
    const stem = normalisedTerm.slice(0, Math.min(4, normalisedTerm.length));
    (card.examples || []).forEach((example, index) => {
      if (!normalise(example).includes(stem)) {
        issues.push(`${card.scopeQuestionId}: example ${index + 1} does not demonstrate ${card.term}`);
      }
    });
  });

  window.WRITING_FIFTEEN_QUESTION_UPDATE_V37_META = {
    sourceName: "Three approved five-question Additional Words batches",
    selectionRule: "Keep a card only when it is useful in a Band 7–8 answer to that exact question, replaces weaker wording and performs a distinct answer function; topic association, difficulty and numerical quotas are not selection rules.",
    batches: [
      Object.keys(approvedTerms).slice(0, 5),
      Object.keys(approvedTerms).slice(5, 10),
      Object.keys(approvedTerms).slice(10, 15),
    ],
    reviewedQuestions,
    questionCardCounts,
    approvedCounts,
    approvedTerms,
    cardCount: cards.length,
    scopedCardCount: cards.filter((card) => reviewedQuestions.includes(card.scopeQuestionId)).length,
    evidenceCardCount: cards.filter((card) => card.replacesBasic && card.essayFunction).length,
    bilingualExampleCardCount: cards.filter((card) => card.examples.length === 3 && card.examplesZh.length === 3).length,
    distinctCardCounts: Array.from(new Set(Object.values(questionCardCounts))).sort((a, b) => a - b),
    rejectedFronts,
    issues,
  };

  delete window.WRITING_V37_ADD_PACK;
})();

/* END data/writing_keyword_update_v37_finalize.js */

;

/* BEGIN data/writing_keyword_update_v38_core.js */
(function () {
  "use strict";

  // V38 contains every approved question completed after the V37 save point:
  // five batches, 25 questions and no hidden per-question card quota.
  // Selection is editorial, not numerical. A card survives only when it helps
  // write that exact Cambridge report or essay and is worth learning for Band 7–8.
  const glossary = window.WRITING_EXACT_KEYWORD_GLOSSARY = window.WRITING_EXACT_KEYWORD_GLOSSARY || {};
  const questionKeywords = window.WRITING_EXACT_QUESTION_KEYWORDS = window.WRITING_EXACT_QUESTION_KEYWORDS || {};
  const state = window.WRITING_TWENTY_FIVE_QUESTION_UPDATE_V38_STATE = {
    reviewedQuestions: [],
    questionCardCounts: {},
    expectedTerms: {},
    cards: [],
    issues: [],
  };

  function slug(text) {
    return String(text).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  function resolveCard(questionId, spec, index) {
    const card = Object.assign({}, spec);
    if (Array.isArray(card.examplePairs)) {
      card.examples = card.examplePairs.map((pair) => pair[0]);
      card.examplesZh = card.examplePairs.map((pair) => pair[1]);
      delete card.examplePairs;
    }

    if (!card.term || !card.pos || !card.meaning || !card.zh) {
      state.issues.push(`${questionId}: card ${index + 1} is missing its learner-facing definition`);
    }
    if (!card.fallback && !card.replacesBasic) {
      state.issues.push(`${questionId}: ${card.term || `card ${index + 1}`} has no weaker-expression target`);
    }
    if (!card.essayFunction) {
      state.issues.push(`${questionId}: ${card.term || `card ${index + 1}`} has no exact-answer function`);
    }
    if (!Array.isArray(card.examples) || !Array.isArray(card.examplesZh)
      || card.examples.length !== 3 || card.examplesZh.length !== 3
      || card.examples.some((item) => !item) || card.examplesZh.some((item) => !item)) {
      state.issues.push(`${questionId}: ${card.term || `card ${index + 1}`} needs three bilingual examples`);
    }
    return card;
  }

  function addPack(questionId, specs) {
    if (state.reviewedQuestions.includes(questionId)) {
      state.issues.push(`${questionId}: duplicate V38 question pack`);
      return;
    }
    if (!Array.isArray(specs) || !specs.length) {
      state.issues.push(`${questionId}: every question must have useful cards`);
      return;
    }

    const cards = specs.map((spec, index) => resolveCard(questionId, spec, index));
    const ids = cards.map((card, index) => {
      const id = `v38-${questionId.toLowerCase()}-${slug(card.term) || `card-${index + 1}`}`;
      const replacesBasic = card.fallback || card.replacesBasic;
      glossary[id] = {
        id,
        term: card.term,
        ipa: "",
        pos: card.pos,
        meaning: card.meaning,
        zh: card.zh,
        zh_def: card.zhDef || `在本題中用來表達「${card.zh}」。`,
        note: `本題升級：用「${card.term}」取代較弱表達「${replacesBasic}」。${card.essayFunction}`,
        examples: card.examples.slice(),
        examplesZh: card.examplesZh.slice(),
        scopeQuestionId: questionId,
        replacesBasic,
        essayFunction: card.essayFunction,
        learningTier: "approved-exact-answer-upgrade-v38",
      };
      state.cards.push(glossary[id]);
      return id;
    });

    if (new Set(ids).size !== ids.length) state.issues.push(`${questionId}: duplicate V38 card ids`);
    questionKeywords[questionId] = ids;
    state.reviewedQuestions.push(questionId);
    state.questionCardCounts[questionId] = ids.length;
    state.expectedTerms[questionId] = cards.map((card) => card.term);
  }

  window.WRITING_V38_ADD_PACK = addPack;
})();

/* END data/writing_keyword_update_v38_core.js */

;

