(function () {
  "use strict";

  const state = window.WRITING_TEN_QUESTION_UPDATE_V39_STATE;
  const glossary = window.WRITING_EXACT_KEYWORD_GLOSSARY || {};
  const questionKeywords = window.WRITING_EXACT_QUESTION_KEYWORDS || {};
  const issues = state && Array.isArray(state.issues) ? state.issues : ["V39 state was not loaded."];

  const approvedTerms = {
    "C19-W2-T3": ["earmark", "accumulate", "cushion", "cultivate", "safeguard", "constrain", "compromise"],
    "C19-W2-T4": ["source", "diversify", "supplement", "stabilise", "undercut", "exacerbate", "vulnerable"],
    "C20-W1-T1": ["soar", "predominate", "peak", "contract", "shift", "overtake", "collectively", "constitute"],
    "C20-W1-T2": ["transition", "repurpose", "relocate", "upgrade", "accommodate", "incorporate", "retain"],
    "C20-W1-T3": ["predominate", "parity", "collectively", "constitute", "marginal", "plateau", "dip", "rebound"],
    "C20-W1-T4": ["cultivate", "undergo", "render", "spin", "weave", "culminate"],
    "C20-W2-T1": ["deprive", "subsidise", "recoup", "deter", "squander", "tiered", "sustain"],
    "C20-W2-T2": ["recharge", "enrichment", "regress", "retain", "disrupt", "alleviate"],
    "C20-W2-T3": ["curtail", "mitigate", "negligible", "forgo", "hamper", "jeopardise", "offset"],
    "C20-W2-T4": ["amplify", "disseminate", "emulate", "diversify", "foster", "converge", "marginalise", "fuel"],
  };
  const approvedCounts = Object.fromEntries(Object.entries(approvedTerms).map(([id, terms]) => [id, terms.length]));

  const rejectedByQuestion = {
    "C19-W2-T3": ["financial literacy", "emergency fund", "compound interest", "disposable income", "inflation", "cost of living", "investment", "job security"],
    "C19-W2-T4": ["food miles", "seasonal produce", "import dependence", "carbon footprint", "consumer behaviour", "sustainability", "globalisation", "quality of life", "logistics"],
    "C20-W1-T1": ["borough", "demographic redistribution", "demographic change", "combined share", "percentage point", "strongest growth"],
    "C20-W1-T2": ["pasture", "orchard", "campsite", "holiday cottage", "solar panel", "land-use conversion", "redevelopment", "commercial", "construct", "green space", "renewable energy", "layout"],
    "C20-W1-T3": ["library membership", "circulation", "loan volume", "adult fiction", "children's fiction", "non-fiction", "age cohort"],
    "C20-W1-T4": ["bamboo stalk", "harvest bamboo", "cut into strips", "crush into pulp", "liquid pulp", "filter out fibres", "fibre separation", "soften the fibres", "amine oxide", "spin into yarn", "garment"],
    "C20-W2-T1": ["water security", "public utility", "cost recovery", "equitable access", "sanitation", "public expenditure", "inequality", "welfare state", "resource allocation"],
    "C20-W2-T2": ["learning loss", "childcare burden", "curriculum continuity", "academic attainment", "work-life balance", "inequality", "curriculum", "burnout"],
    "C20-W2-T3": ["aviation emissions", "frequent flyer", "air connectivity", "carbon emissions", "climate change", "carbon footprint", "economic growth", "revenue", "sustainability", "globalisation", "logistics"],
    "C20-W2-T4": ["fast fashion", "trend diffusion", "cultural homogenisation", "globalisation", "mass media", "consumer behaviour", "cultural identity", "authenticity", "social norms", "commercialisation", "sustainability"],
  };
  const globallyRejectedFronts = [
    "bus station", "staff car park", "shopping centre", "inject", "turbine", "generator",
    "be pumped to a depth of", "be channelled back to the surface", "set the turbine in motion",
    "drive a generator", "electricity distribution", "post-harvest losses", "food insecurity",
    "curriculum continuity", "transferable skills", "digital literacy", "instant gratification",
    "diminished attention span", "compulsive use", "sedentary behaviour", "cultural homogenization",
    "cultural homogenisation", "active ageing", "civil liberties", "income inequality",
  ];

  const reviewedQuestions = state ? state.reviewedQuestions.slice() : [];
  const cards = state ? state.cards.slice() : [];
  const questionCardCounts = state ? Object.assign({}, state.questionCardCounts) : {};

  if (JSON.stringify(reviewedQuestions) !== JSON.stringify(Object.keys(approvedTerms))) {
    issues.push("V39 reviewed-question order or scope drifted from the two approved batches");
  }
  Object.entries(approvedTerms).forEach(([questionId, terms]) => {
    if (questionCardCounts[questionId] !== terms.length) {
      issues.push(`${questionId}: expected ${terms.length} approved cards, found ${questionCardCounts[questionId] || 0}`);
    }
    const liveTerms = (questionKeywords[questionId] || []).map((id) => glossary[id] && glossary[id].term);
    if (JSON.stringify(liveTerms) !== JSON.stringify(terms)) {
      issues.push(`${questionId}: V39 selection drifted before finalisation`);
    }
    const selected = new Set(terms.map((term) => term.toLowerCase()));
    (rejectedByQuestion[questionId] || []).forEach((term) => {
      if (selected.has(term.toLowerCase())) issues.push(`${questionId}: rejected card front returned: ${term}`);
    });
  });

  const selectedTerms = new Set(cards.map((card) => String(card.term || "").toLowerCase()));
  globallyRejectedFronts.forEach((term) => {
    if (selectedTerms.has(term)) issues.push(`Globally rejected V39 card front returned: ${term}`);
  });

  const normalise = (text) => String(text).toLowerCase().replace(/[^a-z0-9]+/g, "");
  cards.forEach((card) => {
    const normalisedTerm = normalise(card.term);
    const stem = normalisedTerm.slice(0, Math.min(4, normalisedTerm.length));
    (card.examples || []).forEach((example, index) => {
      if (!normalise(example).includes(stem)) {
        issues.push(`${card.scopeQuestionId}: example ${index + 1} does not demonstrate ${card.term}`);
      }
    });
  });

  window.WRITING_TEN_QUESTION_UPDATE_V39_META = {
    sourceName: "Final two approved five-question Additional Words batches completing all 80 questions",
    selectionRule: "Keep a card only when it is useful in a Band 7–8 answer to that exact question, replaces weaker wording and performs a distinct answer function; topic association, apparent difficulty and numerical quotas are not selection rules.",
    batches: [Object.keys(approvedTerms).slice(0, 5), Object.keys(approvedTerms).slice(5, 10)],
    reviewedQuestions,
    questionCardCounts,
    approvedCounts,
    approvedTerms,
    cardCount: cards.length,
    scopedCardCount: cards.filter((card) => reviewedQuestions.includes(card.scopeQuestionId)).length,
    evidenceCardCount: cards.filter((card) => card.replacesBasic && card.essayFunction).length,
    bilingualExampleCardCount: cards.filter((card) => card.examples.length === 3 && card.examplesZh.length === 3).length,
    distinctCardCounts: Array.from(new Set(Object.values(questionCardCounts))).sort((a, b) => a - b),
    rejectedByQuestion,
    globallyRejectedFronts,
    issues,
  };

  delete window.WRITING_V39_ADD_PACK;
})();

/* END data/writing_keyword_update_v39_finalize.js */

