/* BEGIN data/writing_paraphrase_repair_v40_finalize.js */
(function () {
  "use strict";

  const api = window.WRITING_PARAPHRASE_V40;
  const paraphrases = window.WRITING_QUESTION_PARAPHRASES;
  const questions = Array.isArray(window.WRITING_SOURCE_QUESTIONS)
    ? window.WRITING_SOURCE_QUESTIONS
    : [];
  if (!api || !paraphrases || typeof paraphrases !== "object") {
    throw new Error("V40 paraphrase repair data was not loaded before finalization");
  }

  const issues = api.issues;
  const prompts = new Map(questions.map((question) => [question.id, String(question.prompt || "")]));
  let pointCount = 0;
  let variantCount = 0;
  let minimumVariants = Infinity;
  let maximumVariants = 0;

  questions.forEach((question) => {
    const points = paraphrases[question.id];
    if (!Array.isArray(points) || !points.length) {
      issues.push(`${question.id}: no paraphrase points after V40 repair`);
      return;
    }
    const used = [];
    points.forEach((point) => {
      const source = String(point && point.source || "");
      const variants = Array.isArray(point && point.variants) ? point.variants : [];
      const occurrence = Math.max(0, Number(point && point.occurrence) || 0);
      let start = -1;
      let searchFrom = 0;
      for (let index = 0; index <= occurrence; index += 1) {
        start = prompts.get(question.id).indexOf(source, searchFrom);
        if (start < 0) break;
        searchFrom = start + source.length;
      }
      if (!source || start < 0) issues.push(`${question.id}: source not found after V40 repair: ${source || "<empty>"}`);
      if (!variants.length) issues.push(`${question.id}: no useful variants after V40 repair: ${source}`);
      if (new Set(variants).size !== variants.length) issues.push(`${question.id}: duplicate variants after V40 repair: ${source}`);
      if (variants.some((variant) => String(variant).trim().toLowerCase() === source.trim().toLowerCase())) {
        issues.push(`${question.id}: source repeated as a V40 variant: ${source}`);
      }
      if (start >= 0) {
        const end = start + source.length;
        if (used.some((range) => start < range.end && end > range.start)) {
          issues.push(`${question.id}: overlapping paraphrase points after V40 repair: ${source}`);
        }
        used.push({ start, end });
      }
      pointCount += 1;
      variantCount += variants.length;
      minimumVariants = Math.min(minimumVariants, variants.length);
      maximumVariants = Math.max(maximumVariants, variants.length);
    });
  });

  Object.keys(paraphrases).forEach((questionId) => {
    if (!prompts.has(questionId)) issues.push(`${questionId}: paraphrase entry has no source question`);
  });

  const counts = api.counts();
  window.WRITING_PARAPHRASE_V40_META = {
    reviewedQuestions: questions.map((question) => question.id),
    changedQuestions: Array.from(api.changedQuestions).sort(),
    questionCount: Object.keys(paraphrases).length,
    pointCount,
    variantCount,
    minimumVariants: Number.isFinite(minimumVariants) ? minimumVariants : 0,
    maximumVariants,
    repairedPoints: counts.repairedPoints,
    addedPoints: counts.addedPoints,
    removedPoints: counts.removedPoints,
    issues: issues.slice(),
  };
})();

/* END data/writing_paraphrase_repair_v40_finalize.js */

;

